<?php
namespace App\Http\Controllers;
use Illuminate\Support\Facades\DB;use Barryvdh\DomPDF\Facade\Pdf;
class ReporteController extends Controller {
 public function boleta($matricula){$m=DB::table('matriculas')->join('estudiantes','estudiantes.id','=','matriculas.estudiante_id')->join('cargas_lectivas','cargas_lectivas.id','=','matriculas.carga_lectiva_id')->where('matriculas.id',$matricula)->select('matriculas.*','estudiantes.codigo_estudiante','estudiantes.apellidos','estudiantes.nombres','cargas_lectivas.unidad_didactica_id')->first();abort_unless($m,404);$notas=DB::table('calificaciones')->join('criterios_evaluacion','criterios_evaluacion.id','=','calificaciones.criterio_evaluacion_id')->where('matricula_id',$matricula)->select('criterios_evaluacion.nombre','criterios_evaluacion.porcentaje','calificaciones.nota')->get();$pdf=Pdf::loadView('reportes.boleta',compact('m','notas'));return $pdf->download('boleta-'.$m->codigo_estudiante.'.pdf');}
 public function acta($carga){$rows=DB::table('matriculas')->join('estudiantes','estudiantes.id','=','matriculas.estudiante_id')->leftJoin('calificaciones','calificaciones.matricula_id','=','matriculas.id')->leftJoin('criterios_evaluacion','criterios_evaluacion.id','=','calificaciones.criterio_evaluacion_id')->where('matriculas.carga_lectiva_id',$carga)->select('estudiantes.codigo_estudiante','estudiantes.apellidos','estudiantes.nombres',DB::raw('ROUND(SUM(calificaciones.nota*criterios_evaluacion.porcentaje/100),2) as promedio'))->groupBy('matriculas.id','estudiantes.codigo_estudiante','estudiantes.apellidos','estudiantes.nombres')->get();$pdf=Pdf::loadView('reportes.acta',compact('rows','carga'));return $pdf->download('acta-consolidada-'.$carga.'.pdf');}
}
